export const UPLC_LOGO_DATA_URI = "data:image/png;base64,";
export const UPLC_LOGO_LIGHT_DATA_URI = "data:image/png;base64,";

export function UplcLogo({
  className = "w-full h-full object-contain",
  light = false
}: {
  className?: string;
  light?: boolean;
}) {
  return (
    <img
      src={light ? UPLC_LOGO_LIGHT_DATA_URI : UPLC_LOGO_DATA_URI}
      alt="UPLC Logo"
      className={className}
    />
  );
}
